/** Covers static utility copy that is intentionally kept close to the workspace view. */
function localizeUtilityContent(element: HTMLElement): void {
  const targetIsZh = isZh.value
  const dictionary = new Map<string, string>()
  for (const [english, chinese] of utilityTranslations) { dictionary.set(english, targetIsZh ? chinese : english); dictionary.set(chinese, targetIsZh ? chinese : english) }
  const walker = document.createTreeWalker(element, NodeFilter.SHOW_TEXT)
  let node: Node | null
  while ((node = walker.nextNode())) { const text = node.nodeValue ?? ''; const trimmed = text.trim(); const translated = dictionary.get(trimmed); if (translated && translated !== trimmed) node.nodeValue = text.replace(trimmed, translated) }
  element.querySelectorAll<HTMLElement>('[placeholder]').forEach((input) => { const translated = dictionary.get(input.getAttribute('placeholder') ?? ''); if (translated) input.setAttribute('placeholder', translated) })
}
const vLocalize = { mounted: (element: HTMLElement) => localizeUtilityContent(element), updated: (element: HTMLElement) => localizeUtilityContent(element) }

function escapeHighlightHtml(value: string): string { return value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;').replaceAll('"', '&quot;') }
const MAX_HIGHLIGHT_LENGTH = 180_000
function highlightJson(value: string): string {
  const tokenPattern = /"(?:\\.|[^"\\])*"|-?\d+(?:\.\d+)?(?:[eE][+-]?\d+)?|true|false|null|[{}\[\],:]/g
  let html = ''; let cursor = 0; let match: RegExpExecArray | null
  while ((match = tokenPattern.exec(value)) !== null) {
    html += escapeHighlightHtml(value.slice(cursor, match.index))
    const token = match[0]
    const next = value.slice(match.index + token.length).match(/^\s*:/)
    const kind = token.startsWith('"') ? (next ? 'key' : 'string') : /^(true|false)$/.test(token) ? 'boolean' : token === 'null' ? 'null' : /^[-\d]/.test(token) ? 'number' : 'punctuation'
    html += `<span class="json-token json-${kind}">${escapeHighlightHtml(token)}</span>`
    cursor = match.index + token.length
  }
  return html + escapeHighlightHtml(value.slice(cursor))
}
function setupJsonHighlight(root: HTMLElement): void {
  root.querySelectorAll<HTMLTextAreaElement>('textarea.code-editor[placeholder*="JSON"], textarea.code-editor[placeholder*="json"]').forEach((textarea) => {
    if (textarea.dataset.jsonHighlightReady) return
    const wrapper = document.createElement('div'); wrapper.className = 'json-editor-shell'; textarea.parentElement?.insertBefore(wrapper, textarea); wrapper.appendChild(textarea)
    const overlay = document.createElement('pre'); overlay.className = 'json-highlight'; wrapper.insertBefore(overlay, textarea)
    const sync = (): void => { if (textarea.value.length > MAX_HIGHLIGHT_LENGTH) overlay.textContent = `${textarea.value}\n`; else overlay.innerHTML = `${highlightJson(textarea.value)}\n`; overlay.scrollTop = textarea.scrollTop; overlay.scrollLeft = textarea.scrollLeft }
    let frame = 0
    const scheduleSync = (): void => { if (frame) cancelAnimationFrame(frame); frame = requestAnimationFrame(() => { frame = 0; sync() }) }
    textarea.addEventListener('input', scheduleSync); textarea.addEventListener('scroll', scheduleSync); textarea.dataset.jsonHighlightReady = 'true'; sync()
  })
  const jsonSection = Array.from(root.querySelectorAll<HTMLElement>('section.workspace-panel')).find((section) => section.querySelector('textarea[placeholder*="JSON"], textarea[placeholder*="json"]'))
  const output = jsonSection?.querySelector<HTMLElement>('pre.code-output')
  if (output && !output.dataset.jsonHighlightReady) { const value = output.textContent ?? ''; if (value.length > MAX_HIGHLIGHT_LENGTH) output.textContent = value; else output.innerHTML = `${highlightJson(value)}\n`; output.dataset.jsonHighlightReady = 'true' }
}
const vJsonHighlight = { mounted: (element: HTMLElement) => setupJsonHighlight(element), updated: (element: HTMLElement) => { element.querySelectorAll<HTMLElement>('[data-json-highlight-ready="true"]').forEach((node) => { if (node.tagName === 'PRE') node.removeAttribute('data-json-highlight-ready') }); setupJsonHighlight(element) } }

function setActiveUtility(id: UtilityId): void { activeUtility.value = id; searchQuery.value = ''; selectedCategory.value = 'all'; if (!['jwt', 'random', 'hash'].includes(id)) recentIds.value = [id, ...recentIds.value.filter((item) => item !== id)].slice(0, 4) }
function toggleFavorite(id: UtilityId): void { favoriteIds.value = favoriteIds.value.includes(id) ? favoriteIds.value.filter((item) => item !== id) : [...favoriteIds.value, id] }
function isCategoryOpen(category: UtilityCategory): boolean { return !collapsedCategories.value.includes(category) }
function toggleCategory(category: UtilityCategory): void { collapsedCategories.value = isCategoryOpen(category) ? [...collapsedCategories.value, category] : collapsedCategories.value.filter((item) => item !== category) }
function onGlobalKeydown(event: KeyboardEvent): void { if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === 'k') { event.preventDefault(); document.querySelector<HTMLInputElement>('.utility-search-input')?.focus() }; if (event.key === 'Escape' && searchQuery.value) searchQuery.value = '' }
function showToast(message: string): void { toast.value = message; window.setTimeout(() => { if (toast.value === message) toast.value = '' }, 1400) }
async function copy(value: string): Promise<void> { copyError.value = ''; if (!value) return; try { await navigator.clipboard.writeText(value); copiedValue.value = value; showToast(isZh.value ? '已复制' : 'Copied'); window.setTimeout(() => { if (copiedValue.value === value) copiedValue.value = '' }, 1400) } catch { copyError.value = t('copyUnavailable') } }
function clearActive(): void { if (activeUtility.value === 'json') { jsonInput.value = ''; jsonChanged.value = ''; jsonOutput.value = ''; jsonError.value = ''; jsonDiffRows.value = [] }; if (activeUtility.value === 'jwt') { jwtInput.value = ''; jwtResult.value = undefined; jwtError.value = '' }; if (activeUtility.value === 'timestamp') { timestampInput.value = ''; timestampResult.value = undefined; timestampError.value = ''; durationResult.value = '' }; if (activeUtility.value === 'regex') { regexPattern.value = ''; regexInput.value = ''; regexReplace.value = ''; regexResult.value = undefined; regexError.value = '' }; if (activeUtility.value === 'text-diff') { diffOriginal.value = ''; diffChanged.value = ''; diffRows.value = [] } }

function runJson(mode: JsonMode): void { jsonMode.value = mode; jsonError.value = ''; try { if (mode === 'diff') { jsonDiffRows.value = diffJson(jsonInput.value, jsonChanged.value); return }; if (mode === 'path') { jsonPathResults.value = queryJson(jsonInput.value, jsonPath.value); return }; if (mode === 'validate') { JSON.parse(jsonInput.value); jsonOutput.value = isZh.value ? 'JSON 有效' : 'Valid JSON'; return }; if (mode === 'escape') jsonOutput.value = escapeJson(jsonInput.value); else if (mode === 'unescape') jsonOutput.value = unescapeJson(jsonInput.value); else if (mode === 'sort') jsonOutput.value = sortJsonKeys(jsonInput.value); else jsonOutput.value = formatJson(jsonInput.value, mode === 'minify') } catch (error) { jsonOutput.value = ''; const diagnostic = diagnoseJson(jsonInput.value); jsonError.value = diagnostic ? `${diagnostic.message} · Line ${diagnostic.line}, Column ${diagnostic.column}` : error instanceof Error ? error.message : t('invalidJson') } }
function useJsonExample(): void { jsonInput.value = '{\n  "users": [\n    { "name": "Ada", "role": "admin" },\n    { "name": "Linus", "role": "maintainer" }\n  ],\n  "localOnly": true\n}'; runJson('format') }
function queryJson(value: string, path: string): unknown[] { const root = JSON.parse(value) as unknown; const segments = path.replace(/^\$\.?/, '').split('.').filter(Boolean); let current: unknown[] = [root]; for (const segment of segments) { const wildcard = segment.endsWith('[*]'); const key = segment.replace('[*]', ''); current = current.flatMap((item) => { const next = key ? (item as Record<string, unknown>)?.[key] : item; return wildcard && Array.isArray(next) ? next : next === undefined ? [] : [next] }) }; return current }
function parseJsonValue(value: string): unknown { try { return JSON.parse(value) as unknown } catch { return null } }
function decodeJwtInput(): void { jwtError.value = ''; try { jwtResult.value = inspectJwt(jwtInput.value) } catch { jwtResult.value = undefined; jwtError.value = t('invalidJwt') } }
function jwtClaimStatus(): { label: string; tone: string } { const now = Date.now() / 1000; const exp = jwtResult.value?.claims.exp; const nbf = jwtResult.value?.claims.nbf; if (typeof exp === 'number' && exp < now) { const minutes = Math.max(1, Math.floor((now - exp) / 60)); return { label: isZh.value ? `已过期 ${minutes} 分钟` : `Expired ${minutes} min ago`, tone: 'danger' } }; if (typeof nbf === 'number' && nbf > now) return { label: isZh.value ? '尚未生效' : 'Not active yet', tone: 'warning' }; if (typeof exp === 'number') { const minutes = Math.max(1, Math.floor((exp - now) / 60)); return { label: isZh.value ? `格式有效 · ${minutes} 分钟后过期` : `Valid format · expires in ${minutes} min`, tone: 'success' } }; return { label: isZh.value ? '格式有效 · 未验证签名' : 'Valid format · signature not verified', tone: 'success' } }
function formatClaim(key: string, value: unknown): string { const date = ['exp', 'nbf', 'iat'].includes(key) ? claimDate(value) : undefined; return date ? `${value} · ${date.toLocaleString()}` : String(value) }
function convertTimestamp(): void { timestampError.value = ''; try { timestampResult.value = formatTimestamp(timestampInput.value) } catch { timestampResult.value = undefined; timestampError.value = t('invalidTimestamp') } }
function setNow(): void { timestampInput.value = String(Date.now()); convertTimestamp() }
function shiftTime(milliseconds: number): void { timestampInput.value = String((timestampResult.value?.milliseconds ?? Date.now()) + milliseconds); convertTimestamp() }
function calculateDuration(): void { const start = Date.parse(durationStart.value); const end = Date.parse(durationEnd.value); if (!Number.isFinite(start) || !Number.isFinite(end) || end < start) { durationResult.value = isZh.value ? '请输入有效的开始和结束时间' : 'Enter valid start and end times'; return }; let seconds = Math.floor((end - start) / 1000); const days = Math.floor(seconds / 86400); seconds %= 86400; const hours = Math.floor(seconds / 3600); seconds %= 3600; const minutes = Math.floor(seconds / 60); durationResult.value = isZh.value ? `${days} 天 ${hours} 小时 ${minutes} 分钟` : `${days} days ${hours} hours ${minutes} minutes` }
function runRegex(): void { regexError.value = ''; try { regexResult.value = regexPattern.value ? testRegex(regexPattern.value, regexFlags.value, regexInput.value) : undefined } catch { regexResult.value = undefined; regexError.value = t('invalidRegex') } }
function runDiff(): void { diffRows.value = diffText(diffOriginal.value, diffChanged.value, { ignoreWhitespace: diffWhitespace.value, ignoreCase: diffCase.value, ignoreEmptyLines: diffEmpty.value }) }
watch([regexPattern, regexFlags, regexInput], runRegex); watch([diffOriginal, diffChanged, diffWhitespace, diffCase, diffEmpty], runDiff)

function generateUuidValue(version: 'v4' | 'v7'): string { const random = new Uint8Array(16); crypto.getRandomValues(random); if (version === 'v7') { const now = BigInt(Date.now()); for (let i = 5; i >= 0; i--) random[5 - i] = Number((now >> BigInt(i * 8)) & 255n); random[6] = (random[6]! & 0x0f) | 0x70 } else random[6] = (random[6]! & 0x0f) | 0x40; random[8] = (random[8]! & 0x3f) | 0x80; const hex = Array.from(random, (byte) => byte.toString(16).padStart(2, '0')).join(''); return uuidHyphen.value ? `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20)}` : hex }
function generateUuids(): void { uuidRows.value = Array.from({ length: Math.min(100, Math.max(1, uuidCount.value)) }, () => { const value = generateUuidValue(uuidVersion.value); return uuidUppercase.value ? value.toUpperCase() : value }) }
function transformBase64(): void { base64Error.value = ''; try { if (base64Mode.value === 'encode') { const encoded = encodeBase64(base64Input.value); base64Output.value = base64UrlSafe.value ? encoded.replaceAll('+', '-').replaceAll('/', '_').replace(/=+$/, '') : encoded } else { const normalized = base64Input.value.replaceAll('-', '+').replaceAll('_', '/').padEnd(Math.ceil(base64Input.value.length / 4) * 4, '='); base64Output.value = decodeBase64(normalized) } } catch { base64Output.value = ''; base64Error.value = t('invalidBase64') } }
function swapBase64(): void { const next = base64Input.value; base64Input.value = base64Output.value; base64Output.value = next; base64Mode.value = base64Mode.value === 'encode' ? 'decode' : 'encode' }
function parseUrlInput(): void { urlError.value = ''; try { urlParts.value = parseUrl(urlInput.value) } catch { urlParts.value = undefined; urlError.value = isZh.value ? '请输入完整 URL，例如 https://example.com/path?id=1' : 'Enter a complete URL, e.g. https://example.com/path?id=1' } }
function rebuildUrl(): void { if (!urlParts.value) return; const base = `${urlParts.value.protocol}://${urlParts.value.host}${urlParts.value.port ? `:${urlParts.value.port}` : ''}${urlParts.value.path}`; const query = new URLSearchParams(urlParts.value.params.map(({ key, value }) => [key, value])).toString(); urlInput.value = `${base}${query ? `?${query}` : ''}${urlParts.value.fragment ? `#${urlParts.value.fragment}` : ''}`; parseUrlInput() }
async function calculateHashes(): Promise<void> { hashing.value = true; hashError.value = ''; try { hashResults.value = await hashAll(hashInput.value); hmacResults.value = hashSecret.value ? { 'HMAC-SHA256': await hmacText(hashInput.value, hashSecret.value, 'HMAC-SHA256'), 'HMAC-SHA512': await hmacText(hashInput.value, hashSecret.value, 'HMAC-SHA512') } : {} } catch { hashError.value = isZh.value ? '当前环境无法计算 Hash' : 'Hash is unavailable in this environment' } finally { hashing.value = false } }
function generateRandom(): void { const symbols = randomSymbols.value ? '!@#$%^&*()_+-=[]{}' : ''; const letters = randomKind.value === 'hex' ? '0123456789abcdef' : `${randomUpper.value ? 'ABCDEFGHIJKLMNOPQRSTUVWXYZ' : ''}${randomLower.value ? 'abcdefghijklmnopqrstuvwxyz' : ''}${randomNumbers.value ? '0123456789' : ''}${symbols}` || '0123456789'; const bytes = new Uint32Array(Math.min(256, Math.max(1, randomLength.value))); crypto.getRandomValues(bytes); randomOutput.value = randomKind.value === 'number' ? Array.from(bytes, (byte) => byte % 10).join('') : Array.from(bytes, (byte) => letters[byte % letters.length]!).join('') }
function describeCron(expression: string, flavor: string): string { const fields = expression.trim().split(/\s+/); if ((flavor === 'linux' && fields.length !== 5) || (flavor === 'quartz' && ![6, 7].includes(fields.length))) return isZh.value ? '表达式位数与所选 Cron 类型不匹配' : 'Field count does not match this Cron flavor'; const minute = fields[flavor === 'linux' ? 0 : 1]!; if (minute.startsWith('*/')) return isZh.value ? `每 ${minute.slice(2)} 分钟` : `Every ${minute.slice(2)} minutes`; return isZh.value ? '自定义调度' : 'Custom schedule' }
function nextCronExecutions(expression: string, flavor: string): string[] { if (!/^\*/.test(expression.trim())) return []; const step = Number(expression.trim().split(/\s+/)[flavor === 'linux' ? 0 : 1]?.replace('*/', '')); if (!Number.isFinite(step) || step < 1) return []; const next: string[] = []; let cursor = new Date(); cursor.setSeconds(0, 0); for (let i = 0; next.length < 5 && i < 120; i++) { cursor = new Date(cursor.getTime() + 60000); if (cursor.getMinutes() % step === 0) next.push(cursor.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })) } return next }
onMounted(() => window.addEventListener('keydown', onGlobalKeydown)); onUnmounted(() => window.removeEventListener('keydown', onGlobalKeydown))
</script>

<template>
  <section class="view utilities-view">
    <header class="view-header utilities-header"><div><p class="eyebrow">{{ isZh ? '本地开发工作台' : 'LOCAL DEVELOPER WORKSPACE' }}</p><h1>{{ t('utilities') }}</h1><p>{{ isZh ? '把开发过程中随手要用的转换、检查和比较留在本机。' : 'Keep the small conversions, checks and comparisons of development close at hand.' }}</p></div><div class="utility-header-meta"><span class="local-badge"><span />{{ isZh ? '仅本地处理' : 'LOCAL ONLY' }}</span><span class="shortcut-hint"><kbd>⌘</kbd><kbd>K</kbd> {{ isZh ? '搜索工具' : 'Search tools' }}</span></div></header>
    <div class="utility-shell">
      <aside class="utility-nav" aria-label="Utilities navigation">
        <label class="utility-search"><Search :size="15" /><input v-model="searchQuery" class="utility-search-input" type="search" :placeholder="isZh ? '搜索工具…' : 'Search tools…'" aria-label="Search tools" /><kbd>⌘K</kbd></label>
        <div v-if="searchQuery" class="utility-search-results"><button v-for="definition in filteredDefinitions" :key="definition.id" class="utility-nav-item" :class="{ active: activeUtility === definition.id }" @click="setActiveUtility(definition.id)"><component :is="definition.icon" :size="15" /><span>{{ definitionLabel(definition) }}<small>{{ definitionDescription(definition) }}</small></span></button><p v-if="!filteredDefinitions.length" class="utility-empty">{{ isZh ? '没有匹配工具' : 'No matching tools' }}</p></div>
        <template v-else><div class="utility-nav-heading"><span>{{ isZh ? '常用' : 'FREQUENT' }}</span><Star :size="13" /></div><button v-for="definition in favoriteDefinitions" :key="`favorite-${definition.id}`" class="utility-nav-item" :class="{ active: activeUtility === definition.id }" @click="setActiveUtility(definition.id)"><component :is="definition.icon" :size="15" /><span>{{ definitionLabel(definition) }}<small>{{ definitionDescription(definition) }}</small></span></button><div v-for="category in utilityCategories.slice(1)" :key="category.id" class="utility-category"><button class="utility-category-title" :class="{ selected: selectedCategory === category.id }" :aria-expanded="isCategoryOpen(category.id)" @click="toggleCategory(category.id)"><span>{{ categoryLabel(category.id) }}</span><small>{{ isCategoryOpen(category.id) ? '⌃' : '⌄' }} {{ category.ids.length }}</small></button><div v-show="isCategoryOpen(category.id)" class="utility-category-items"><button v-for="id in category.ids.filter((item, index, list) => list.indexOf(item) === index)" :key="`${category.id}-${id}`" class="utility-sub-item" :class="{ active: activeUtility === id }" @click="setActiveUtility(id)">{{ definitionLabel(utilityDefinitions.find((item) => item.id === id)!) }}</button></div></div><div v-if="recentDefinitions.length" class="utility-recent"><div class="utility-nav-heading"><span>{{ isZh ? '最近使用' : 'RECENT' }}</span><button class="icon-button" @click="recentIds = []"><X :size="13" /></button></div><button v-for="definition in recentDefinitions" :key="`recent-${definition.id}`" class="utility-sub-item" @click="setActiveUtility(definition.id)">{{ definitionLabel(definition) }}</button></div></template>
      </aside>
      <main ref="utilityRoot" v-localize v-json-highlight class="utility-main">
        <div class="utility-workspace-heading"><div class="utility-title-line"><component :is="activeDefinition.icon" :size="18" /><div><h2>{{ definitionLabel(activeDefinition) }}</h2><p>{{ definitionDescription(activeDefinition) }}</p></div></div><button class="icon-button favorite-toggle" @click="toggleFavorite(activeUtility)"><Star v-if="favoriteIds.includes(activeUtility)" :size="16" fill="currentColor" /><StarOff v-else :size="16" /></button></div>
        <div class="utility-toolbar"><span class="utility-state"><span class="state-dot" />{{ isZh ? '就绪 · 数据不会离开本机' : 'Ready · data stays on this device' }}</span><span class="toolbar-spacer" /><button class="ghost-button" :disabled="['uuid', 'cron', 'random'].includes(activeUtility)" @click="clearActive"><Eraser :size="13" />{{ t('clearTool') }}</button><span v-if="copyError" class="utility-error">{{ copyError }}</span></div>

        <section v-if="activeUtility === 'json'" class="utility-panel workspace-panel"><div class="mode-tabs"><button v-for="mode in (['format', 'minify', 'validate', 'escape', 'unescape', 'sort', 'diff', 'path', 'tree'] as JsonMode[])" :key="mode" :class="{ active: jsonMode === mode }" @click="runJson(mode)">{{ ({ format: 'Format', minify: 'Minify', validate: 'Validate', escape: 'Escape', unescape: 'Unescape', sort: 'Sort keys', diff: 'JSON Diff', path: 'JSONPath', tree: 'Tree' }[mode]) }}</button></div><div v-if="jsonMode === 'diff'" class="editor-grid"><label class="editor-box"><span>Original</span><textarea v-model="jsonInput" class="code-editor" spellcheck="false" placeholder="Paste original JSON…" /></label><label class="editor-box"><span>Changed</span><textarea v-model="jsonChanged" class="code-editor" spellcheck="false" placeholder="Paste changed JSON…" /></label></div><div v-else-if="jsonMode === 'path'" class="editor-grid"><label class="editor-box"><span>JSON</span><textarea v-model="jsonInput" class="code-editor" spellcheck="false" placeholder="Paste JSON…" /></label><div class="result-box"><label>Query</label><input v-model="jsonPath" class="utility-input" @keydown.enter="runJson('path')" /><pre class="code-output">{{ jsonPathResults.length ? JSON.stringify(jsonPathResults, null, 2) : 'Run a query to inspect matches.' }}</pre></div></div><div v-else class="editor-grid"><label class="editor-box"><span>Input</span><textarea v-model="jsonInput" class="code-editor" spellcheck="false" placeholder="Paste JSON…" @keydown.ctrl.enter.prevent="runJson('format')" @keydown.meta.enter.prevent="runJson('format')" /></label><div class="result-box"><label>Output</label><pre v-if="jsonMode !== 'tree'" class="code-output">{{ jsonOutput }}</pre><div v-else class="json-tree-output"><JsonTree v-if="jsonOutput" :value="parseJsonValue(jsonOutput)" /><p v-else class="utility-empty">{{ isZh ? '先运行一次 JSON 操作' : 'Run a JSON operation first' }}</p></div></div></div><div class="utility-actions"><button class="primary" @click="runJson(jsonMode)">{{ jsonMode === 'validate' ? 'Validate' : jsonMode === 'path' ? 'Run query' : jsonMode === 'diff' ? 'Compare' : 'Run' }}</button><button class="ghost-button" @click="useJsonExample">Example</button><button class="ghost-button" :disabled="!jsonOutput" @click="copy(jsonOutput)"><Copy :size="13" />{{ copyLabel }}</button><button class="ghost-button" :disabled="!jsonOutput" @click="jsonInput = jsonOutput"><SwitchCamera :size="13" />Swap</button></div><p v-if="jsonError" class="utility-error status-line"><ShieldAlert :size="14" />{{ jsonError }}</p><p class="utility-note">Ctrl / ⌘ + Enter to format · Results are processed locally</p><div v-if="jsonMode === 'diff' && jsonDiffRows.length" class="structured-diff json-structured-diff"><div v-for="(row, index) in jsonDiffRows" :key="`${index}-${row.path}`" :class="`diff-row ${row.type}`"><span>{{ row.type === 'added' ? '+' : row.type === 'removed' ? '−' : '~' }}</span><code>{{ row.path }} · {{ row.type === 'changed' ? `${JSON.stringify(row.before)} → ${JSON.stringify(row.after)}` : JSON.stringify(row.after ?? row.before) }}</code></div></div></section>

        <section v-else-if="activeUtility === 'jwt'" class="utility-panel workspace-panel"><div class="editor-box"><span>Token</span><textarea v-model="jwtInput" class="code-editor jwt-editor" spellcheck="false" :placeholder="t('jwtInputPlaceholder')" @input="decodeJwtInput" /></div><div class="utility-actions"><button class="primary" :disabled="!jwtInput.trim()" @click="decodeJwtInput">Decode JWT</button><button class="ghost-button" :disabled="!jwtResult" @click="copy(`${JSON.stringify(jwtResult?.header, null, 2)}\n${JSON.stringify(jwtResult?.claims, null, 2)}`)"><Copy :size="13" />{{ copyLabel }}</button><span class="utility-note">Header and payload are decoded locally. Signature is never assumed valid.</span></div><p v-if="jwtError" class="utility-error status-line"><ShieldAlert :size="14" />{{ jwtError }}</p><div v-if="jwtResult" class="jwt-grid"><div class="result-box"><label>Header <code>{{ jwtResult.algorithm }}</code></label><pre class="code-output">{{ JSON.stringify(jwtResult.header, null, 2) }}</pre></div><div class="result-box"><label>Payload <span class="claim-status" :class="jwtClaimStatus().tone">{{ jwtClaimStatus().label }}</span></label><pre class="code-output">{{ JSON.stringify(jwtResult.payload, null, 2) }}</pre></div><div class="result-box jwt-signature"><label>Signature <small>Not verified</small></label><pre class="code-output">{{ jwtResult.signature }}</pre></div></div><dl v-if="jwtResult" class="claims-grid"><div v-for="key in ['iss', 'sub', 'aud', 'exp', 'nbf', 'iat', 'jti']" :key="key"><dt>{{ key }}</dt><dd v-if="jwtResult.claims[key] !== undefined">{{ formatClaim(key, jwtResult.claims[key]) }}</dd><dd v-else class="muted">—</dd></div></dl></section>

        <section v-else-if="activeUtility === 'timestamp'" class="utility-panel workspace-panel"><div class="time-input-row"><input v-model="timestampInput" class="utility-input" type="text" :placeholder="t('timestampInputPlaceholder')" @keydown.enter="convertTimestamp" /><button class="primary" @click="convertTimestamp">Convert</button><button class="ghost-button" @click="setNow">Now</button><button class="ghost-button" :disabled="!timestampResult" @click="shiftTime(3600000)">+1 hour</button><button class="ghost-button" :disabled="!timestampResult" @click="shiftTime(86400000)">+1 day</button><button class="ghost-button" :disabled="!timestampResult" @click="shiftTime(-86400000)">−1 day</button></div><p v-if="timestampError" class="utility-error status-line"><ShieldAlert :size="14" />{{ timestampError }}</p><div v-if="timestampResult" class="time-results"><div v-for="item in [{ label: 'Local time', value: timestampResult.local }, { label: 'UTC', value: timestampResult.iso }, { label: 'Unix seconds', value: timestampResult.seconds }, { label: 'Unix milliseconds', value: timestampResult.milliseconds }, { label: 'ISO 8601', value: timestampResult.iso }]" :key="item.label"><span>{{ item.label }}</span><code>{{ item.value }}</code><button class="icon-button" @click="copy(String(item.value))"><Copy :size="13" /></button></div></div><div class="duration-block"><div class="section-kicker">Duration calculator</div><div class="time-input-row"><input v-model="durationStart" class="utility-input" type="datetime-local" /><span class="muted">→</span><input v-model="durationEnd" class="utility-input" type="datetime-local" /><button class="ghost-button" @click="calculateDuration">Calculate</button></div><p v-if="durationResult" class="duration-result">{{ durationResult }}</p></div></section>

        <section v-else-if="activeUtility === 'regex'" class="utility-panel workspace-panel"><div class="regex-toolbar"><label>Pattern<input v-model="regexPattern" class="utility-input" placeholder="(error|warn)\s+(.+)" /></label><label class="flags-field">Flags<input v-model="regexFlags" class="utility-input" /></label><label>Runtime<select class="utility-input"><option>JavaScript</option><option disabled>Java · syntax reference</option><option disabled>Python · syntax reference</option><option disabled>Go · syntax reference</option></select></label></div><label class="editor-box"><span>Test text</span><textarea v-model="regexInput" class="code-editor regex-editor" spellcheck="false" placeholder="Paste text to inspect…" /></label><div class="replace-row"><label>Replace<input v-model="regexReplace" class="utility-input" placeholder="$1" /></label><label class="replace-preview">Replace preview<code>{{ regexPreview || '—' }}</code></label><button class="ghost-button" :disabled="!regexResult" @click="copy(JSON.stringify(regexResult, null, 2))"><Copy :size="13" />{{ copyLabel }}</button></div><p v-if="regexError" class="utility-error status-line"><ShieldAlert :size="14" />{{ regexError }}</p><div v-if="regexResult" class="regex-summary"><strong>{{ regexResult.matches.length }}</strong> {{ isZh ? '个匹配' : 'matches' }}<span v-if="regexResult.truncated"> · first 1000</span></div><div v-if="regexResult?.matches.length" class="regex-match-list"><div v-for="(match, index) in regexResult.matches" :key="`${index}-${match.index}`" class="regex-match-row"><strong>Match {{ index + 1 }}</strong><code>{{ match.value || '∅' }}</code><span>position {{ match.index }}</span><small v-if="match.groups.length">Capture groups: {{ match.groups.join(' · ') }}</small></div></div></section>

        <section v-else-if="activeUtility === 'text-diff'" class="utility-panel workspace-panel"><div class="diff-toolbar"><div class="mode-tabs"><button :class="{ active: diffView === 'split' }" @click="diffView = 'split'">Side by side</button><button :class="{ active: diffView === 'inline' }" @click="diffView = 'inline'">Inline</button></div><label><input v-model="diffWhitespace" type="checkbox" /> Ignore whitespace</label><label><input v-model="diffCase" type="checkbox" /> Ignore case</label><label><input v-model="diffEmpty" type="checkbox" /> Ignore empty lines</label></div><div v-if="diffView === 'split'" class="editor-grid"><label class="editor-box"><span>Original</span><textarea v-model="diffOriginal" class="code-editor" spellcheck="false" placeholder="Paste original…" /></label><label class="editor-box"><span>Changed</span><textarea v-model="diffChanged" class="code-editor" spellcheck="false" placeholder="Paste changed…" /></label></div><div v-else class="structured-diff"><div v-for="(row, index) in diffRows" :key="`${index}-${row.line}`" :class="`diff-row ${row.type}`"><span>{{ row.type === 'added' ? '+' : row.type === 'removed' ? '−' : ' ' }}</span><code>{{ row.value }}</code></div></div><div class="utility-actions"><button class="primary" @click="runDiff">Compare</button><button class="ghost-button" :disabled="!diffRows.length" @click="copy(diffRows.map((row) => `${row.type}: ${row.value}`).join('\n'))"><Copy :size="13" />{{ copyLabel }}</button></div><div v-if="diffRows.length" class="diff-summary"><span class="added-dot" />{{ diffRows.filter((row) => row.type === 'added').length }} added <span class="removed-dot" />{{ diffRows.filter((row) => row.type === 'removed').length }} removed</div></section>

        <section v-else-if="activeUtility === 'uuid'" class="utility-panel workspace-panel"><div class="settings-row"><label>Version<select v-model="uuidVersion" class="utility-input"><option value="v4">UUID v4 · random</option><option value="v7">UUID v7 · time-sortable</option></select></label><label>Count<input v-model.number="uuidCount" class="utility-input" type="number" min="1" max="100" /></label><label class="check-label"><input v-model="uuidUppercase" type="checkbox" /> Uppercase</label><label class="check-label"><input v-model="uuidHyphen" type="checkbox" /> Hyphen</label><button class="primary" @click="generateUuids">Generate</button></div><div class="uuid-list"><div v-for="(row, index) in uuidRows" :key="`${row}-${index}`"><code>{{ row }}</code><button class="icon-button" @click="copy(row)"><Copy :size="13" /></button></div><p v-if="!uuidRows.length" class="utility-empty">Generate a batch of local IDs.</p></div><button class="ghost-button" :disabled="!uuidRows.length" @click="copy(uuidRows.join('\n'))"><Clipboard :size="13" />Copy all</button></section>

        <section v-else-if="activeUtility === 'base64'" class="utility-panel workspace-panel"><div class="mode-tabs"><button :class="{ active: base64Mode === 'encode' }" @click="base64Mode = 'encode'">Text → Base64</button><button :class="{ active: base64Mode === 'decode' }" @click="base64Mode = 'decode'">Base64 → Text</button><label class="check-label"><input v-model="base64UrlSafe" type="checkbox" /> Base64URL</label></div><div class="editor-grid"><label class="editor-box"><span>Input</span><textarea v-model="base64Input" class="code-editor" spellcheck="false" /></label><div class="result-box"><label>Output</label><pre class="code-output">{{ base64Output }}</pre></div></div><div class="utility-actions"><button class="primary" @click="transformBase64">{{ base64Mode === 'encode' ? 'Encode' : 'Decode' }}</button><button class="ghost-button" @click="swapBase64"><SwitchCamera :size="13" />Swap</button><button class="ghost-button" :disabled="!base64Output" @click="copy(base64Output)"><Copy :size="13" />{{ copyLabel }}</button></div><p v-if="base64Error" class="utility-error status-line">{{ base64Error }}</p></section>

        <section v-else-if="activeUtility === 'url'" class="utility-panel workspace-panel"><div class="editor-box"><span>URL</span><input v-model="urlInput" class="utility-input" placeholder="https://example.com/api/users?id=1&name=test" @keydown.enter="parseUrlInput" /></div><div class="utility-actions"><button class="primary" @click="parseUrlInput">Parse URL</button><button class="ghost-button" @click="copy(urlInput)"><Copy :size="13" />{{ copyLabel }}</button></div><p v-if="urlError" class="utility-error status-line">{{ urlError }}</p><div v-if="urlParts" class="url-inspector"><div v-for="key in ['protocol', 'host', 'port', 'path', 'query', 'fragment']" :key="key"><span>{{ key }}</span><code>{{ urlParts[key as keyof typeof urlParts] || '—' }}</code></div><div class="query-table"><strong>Query parameters</strong><div v-for="(param, index) in urlParts.params" :key="index"><input v-model="param.key" class="utility-input" /><input v-model="param.value" class="utility-input" /></div><button class="ghost-button" @click="urlParts.params.push({ key: 'key', value: 'value' })">+ Add parameter</button><button class="primary" @click="rebuildUrl">Rebuild URL</button></div></div></section>

